function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function sourceLinks(ids, open=false){return `<details class="references" ${open?'open':''}><summary>Sources & further reading · ${ids.length}</summary>${ids.map(id=>sourceLink(sourceById[id])).join('')}<p class="foot-note">Original study summaries. Open the linked source for its full context; external pages need internet.</p></details>`;}
